def ifft(spectrum: np.ndarray) -> np.ndarray:

    fft_back = np.fft.ifftshift(spectrum)
    complex_signal_back = np.fft.ifft(fft_back)
    return np.real(complex_signal_back)

def tau_array(configs: SimpleNamespace) -> np.ndarray:
    return (configs.R / configs.c) * np.cos(
        configs.target_phi - gamma_array(configs.M)
    )

def complex_steering_vector(
    phi: float, tau_array: np.ndarray, f0: float, M: int
) -> np.ndarray:

    return np.array(
        [
            x
            for i in range(M)
            for x in np.array([1, np.cos(phi), np.sin(phi)])
            * np.exp(-2j * np.pi * f0 * tau_array[i])
        ]
    ).T

def complex_steering_matrix(configs: SimpleNamespace) -> np.ndarray:
    res = []

    for phi in configs.phi_vector:
        config_copy = copy(configs)
        config_copy.target_phi = phi
        taus = model.tau_array(config_copy)
        res.append(complex_steering_vector(phi, taus, configs.f0, configs.M))
    return np.array(res)

def f_rms(spectrum: np.ndarray, configs: SimpleNamespace):
    return np.abs(
        np.sqrt(
            np.trapezoid(
                y=(configs.freq_vector * np.abs(spectrum)) ** 2,
                x=configs.freq_vector,
            )
            / (np.trapezoid(y=np.abs(spectrum) ** 2, x=configs.freq_vector))
        )
    )
